This function has a bug. Fix it.

Source:
```typescript
export function groupBy<T>(items: T[], key: keyof T): Record<string, T[]> {
  const result: Record<string, T[]> = {};
  for (const item of items) {
    const groupKey = String(item[key]);
    if (!result[groupKey]) {
      result[groupKey] = [];
    }
    result[groupKey] = [item];
  }
  return result;
}
```

Failing test:
```
const data = [
  { name: 'Alice', dept: 'eng' },
  { name: 'Bob', dept: 'eng' },
  { name: 'Carol', dept: 'sales' }
];
const grouped = groupBy(data, 'dept');
assert(grouped['eng'].length === 2); // FAILS: got 1
assert(grouped['sales'].length === 1); // passes
```

Error: `AssertionError: Expected 2 but got 1`
